namespace sv_e587c54695ea4d44b341a6f3a1a2fea8.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// In Blazor Server, scoped = per-circuit, so each user gets independent state.
/// </summary>
public class ThemeService
{
    public ThemeMode Mode { get; private set; } = ThemeMode.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    public event Action? OnChange;

    public void SetMode(ThemeMode mode)
    {
        if (Mode == mode) return;
        Mode = mode;
        NotifyStateChanged();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        NotifyStateChanged();
    }

    public void SetTheme(ThemeMode mode, string accentColor)
    {
        var changed = Mode != mode || AccentColor != accentColor;
        Mode = mode;
        AccentColor = accentColor;
        if (changed) NotifyStateChanged();
    }

    private void NotifyStateChanged() => OnChange?.Invoke();
}

@rendermode InteractiveServer
@inject ThemeService ThemeService
@inject IJSRuntime JS
@implements IDisposable

<span class="theme-indicator" style="color: @ThemeService.AccentColor;">
    @GetIcon() @ThemeService.Mode
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += OnThemeChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            await ApplyThemeToDocument();
        }
    }

    private async void OnThemeChanged()
    {
        await InvokeAsync(async () =>
        {
            StateHasChanged();
            await ApplyThemeToDocument();
        });
    }

    private async Task ApplyThemeToDocument()
    {
        var theme = ThemeService.Mode.ToString().ToLowerInvariant();
        await JS.InvokeVoidAsync("applyTheme", theme, ThemeService.AccentColor);
    }

    private string GetIcon() => ThemeService.Mode switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        ThemeMode.System => "💻",
        _ => ""
    };

    public void Dispose()
    {
        ThemeService.OnChange -= OnThemeChanged;
    }
}

@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<div class="theme-toggle">
    <button class="btn btn-sm @ButtonClass(ThemeMode.Light)" @onclick="() => ThemeService.SetMode(ThemeMode.Light)">☀️</button>
    <button class="btn btn-sm @ButtonClass(ThemeMode.Dark)" @onclick="() => ThemeService.SetMode(ThemeMode.Dark)">🌙</button>
    <button class="btn btn-sm @ButtonClass(ThemeMode.System)" @onclick="() => ThemeService.SetMode(ThemeMode.System)">💻</button>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += OnThemeChanged;
    }

    private void OnThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string ButtonClass(ThemeMode mode) =>
        ThemeService.Mode == mode ? "btn-primary" : "btn-outline-secondary";

    public void Dispose()
    {
        ThemeService.OnChange -= OnThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService ThemeService
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card p-4" style="max-width: 500px;">
    <h4>Theme</h4>
    <div class="mb-3">
        <label class="form-label">Mode</label>
        <select class="form-select" value="@ThemeService.Mode" @onchange="OnModeChanged">
            @foreach (var mode in Enum.GetValues<ThemeMode>())
            {
                <option value="@mode">@mode</option>
            }
        </select>
    </div>

    <div class="mb-3">
        <label class="form-label">Accent Color</label>
        <input type="color" class="form-control form-control-color"
               value="@ThemeService.AccentColor"
               @onchange="OnColorChanged" />
        <small class="text-muted">Current: @ThemeService.AccentColor</small>
    </div>

    <hr />
    <p><strong>Live preview:</strong></p>
    <p style="color: @ThemeService.AccentColor;">
        This text uses your accent color. Mode: @ThemeService.Mode
    </p>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += OnThemeChanged;
    }

    private void OnModeChanged(ChangeEventArgs e)
    {
        if (Enum.TryParse<ThemeMode>(e.Value?.ToString(), out var mode))
        {
            ThemeService.SetMode(mode);
        }
    }

    private void OnColorChanged(ChangeEventArgs e)
    {
        ThemeService.SetAccentColor(e.Value?.ToString() ?? "#0d6efd");
    }

    private void OnThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= OnThemeChanged;
    }
}

window.applyTheme = function (mode, accentColor) {
    const html = document.documentElement;
    html.setAttribute('data-theme', mode);
    html.style.setProperty('--accent-color', accentColor);
};

