    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        ThemeMode.System => "💻",
        _ => ""
    };

    public void Dispose()
    {
        ThemeService.OnChange -= OnThemeChanged;
    }
}

